const SUGGESTION_TYPES = ["건의사항", "장소 요청", "기타"];

/* Wishlist ("찜") entries are stored as suggestions with a fixed id per family + program,
   so each family counts once per program. resolved=true means the family un-saved it. */
const WISH_TYPE = "찜";
const KAKAO_CHAT_URL = ""; // paste the KakaoTalk channel / open-chat link here to show a "카카오톡으로 문의하기" button
const wishId = (familyPin, programId) => `wish-${familyPin}-${programId}`;
const isWish = (sg) => sg.type === WISH_TYPE;

/* App visits (customers only): one small row per family per day, saved the first time a parent
   logs in that day. Teacher logins are never counted. Day = Korea time. */
const VISIT_TYPE = "방문";
const kstDay = (d = new Date()) => d.toLocaleDateString("en-CA", { timeZone: "Asia/Seoul" });
const visitId = (familyPin, day) => `visit-${familyPin}-${day}`;
const isVisit = (sg) => sg.type === VISIT_TYPE;
/* ================================================================== */
/*  CARROTWORLD POINTS                                                  */
/*  Experience completed +1,000P · parent survey +100P · external review */
/*  +300P (after a staff check) · friend referral +2,000P (set by staff). */
/*  1P = 1 won. Points are used for the next program's payment and can   */
/*  never be paid out in cash.                                           */
/*  The balance is always WORKED OUT from the records (attendance,       */
/*  surveys, approved reviews, staff entries), so it can never drift.    */
/*  Everything stored is "create only" rows (like wishes and visits):    */
/*  a review link, its decision, "seen by the parent", staff entries.    */
/* ================================================================== */
/** HQ's list of point items. The first four are built in (trip, survey and review are counted by the app, referral is added by staff);
 *  HQ can change their names and amounts and add items of its own that staff give by hand. */
const BUILT_IN_POINT_IDS = ["trip", "survey", "review", "referral"];
const DEFAULT_POINT_ITEMS = [
  { id: "trip", name: "체험 프로그램 완료", title: "Experience Completed", amount: 1000, note: "" },
  { id: "survey", name: "부모 설문 완료", title: "Parent Survey", amount: 100, note: "" },
  { id: "review", name: "외부 후기 작성", title: "External Review", amount: 300, note: "후기 링크 확인 후 적립" },
  { id: "referral", name: "친구 추천", title: "Friend Referral", amount: 2000, note: "추천받은 친구가 첫 결제를 완료하면 적립" },
];
/** The amounts in force right now. They are refreshed from HQ's saved items every time a screen is drawn, so every text follows. */
const POINT_RULES = { trip: 1000, survey: 100, review: 300, referral: 2000 };
let POINT_ITEMS = DEFAULT_POINT_ITEMS;
const REVIEW_TYPE = "외부후기";
const REVIEW_RESULT_TYPE = "외부후기결과";
const REVIEW_SEEN_TYPE = "외부후기확인";
const POINT_TYPE = "포인트";
const isPointRow = (sg) => sg.type === REVIEW_TYPE || sg.type === REVIEW_RESULT_TYPE || sg.type === REVIEW_SEEN_TYPE || sg.type === POINT_TYPE;
const fmtBalance = (n) => `${Number(n || 0).toLocaleString("en-US")}P`;
const fmtDelta = (n) => `${n < 0 ? "−" : "+"}${Math.abs(n).toLocaleString("en-US")}P`;
const fmtDay = (iso) => {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleDateString("ko-KR", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).replace(/\.\s*/g, ".").replace(/\.$/, "");
};
const readRow = (sg) => {
  try {
    return JSON.parse(sg.message || "{}") || {};
  } catch (e) {
    return {};
  }
};
const friendKey = (name) => String(name || "").trim().toLowerCase().replace(/\s+/g, "");

/** A review link must be a real, public post address, and the same post can never be used twice. */
function normalizeReviewUrl(raw) {
  const BAD = "올바른 링크가 아니에요. 후기 게시물의 주소(https://…)를 그대로 붙여넣어 주세요.";
  let t = String(raw || "").trim();
  if (!t) return { ok: false, error: "후기 링크를 붙여넣어 주세요." };
  if (/\s/.test(t)) return { ok: false, error: "링크에 띄어쓰기가 있어요. 게시물 주소만 붙여넣어 주세요." };
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(t)) t = `https://${t}`;
  let u;
  try {
    u = new URL(t);
  } catch (e) {
    return { ok: false, error: BAD };
  }
  if (!/^https?:$/.test(u.protocol) || !u.hostname.includes(".")) return { ok: false, error: BAD };
  const host = u.hostname.toLowerCase().replace(/^(www|m)\./, "");
  if (host === "carrotworld.kr" || host.endsWith(".carrotworld.kr")) return { ok: false, error: "당근나라 사이트 주소는 쓸 수 없어요. 네이버, 인스타그램 같은 외부 게시물 링크를 붙여넣어 주세요." };
  const query = [...u.searchParams.entries()]
    .filter(([k]) => !/^(utm_|fbclid|igshid|igsh$|ref$|share)/i.test(k))
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}=${v}`)
    .join("&");
  const path = u.pathname.replace(/\/+$/, "");
  if (!path && !query) return { ok: false, error: "게시물 주소가 아니라 사이트 첫 화면 주소예요. 후기 글의 주소를 붙여넣어 주세요." };
  return { ok: true, url: u.toString(), norm: `${host}${path}${query ? `?${query}` : ""}`.toLowerCase() };
}

/** Every submitted review link with its latest decision (pending until staff decide; the last decision wins). */
function reviewRecords(suggestions) {
  const subs = suggestions.filter((sg) => sg.type === REVIEW_TYPE).map((sg) => ({ id: sg.id, familyPin: sg.familyPin, ...readRow(sg) }));
  const results = suggestions.filter((sg) => sg.type === REVIEW_RESULT_TYPE).map(readRow);
  const seen = new Set(suggestions.filter((sg) => sg.type === REVIEW_SEEN_TYPE).map((sg) => readRow(sg).submissionId));
  return subs
    .map((r) => {
      const mine = results.filter((x) => x.submissionId === r.id).sort((a, b) => String(a.decidedAt).localeCompare(String(b.decidedAt)));
      const last = mine[mine.length - 1];
      return { ...r, status: last ? last.status : "pending", decidedAt: last ? last.decidedAt : null, seen: seen.has(r.id) };
    })
    .sort((a, b) => String(b.submittedAt).localeCompare(String(a.submittedAt)));
}
const latestReview = (records, pin, programId) => records.find((r) => r.familyPin === pin && r.programId === programId) || null;
const reviewUrlTaken = (records, norm) => records.some((r) => r.norm === norm && r.status !== "rejected");

const clampAmount = (v, fallback) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) && n >= 0 && n <= 1000000 ? n : fallback;
};
/** Keeps the four built-in items (with HQ's changes) and the items HQ added. */
function normalizePointItems(items) {
  const out = DEFAULT_POINT_ITEMS.map((d) => {
    const f = (items || []).find((i) => i.id === d.id);
    return f ? { ...d, name: String(f.name || d.name), title: String(f.title || d.title), note: f.note === undefined ? d.note : String(f.note || ""), amount: clampAmount(f.amount, d.amount) } : d;
  });
  (items || []).filter((i) => i && i.id && !BUILT_IN_POINT_IDS.includes(i.id) && String(i.name || "").trim()).forEach((i) => out.push({ id: String(i.id), name: String(i.name).trim(), title: String(i.title || i.name).trim(), note: String(i.note || ""), amount: clampAmount(i.amount, 0), custom: true }));
  return out;
}
/** Every saved version of the items, oldest first (the first one is the built-in default). */
function pointVersions(suggestions) {
  const rows = (suggestions || []).filter((sg) => sg.type === SETTING_TYPE).map(readRow).filter((r) => r.key === "pointItems" && Array.isArray(r.items)).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  return [{ at: "", items: DEFAULT_POINT_ITEMS }, ...rows.map((r) => ({ at: r.at || "", items: normalizePointItems(r.items) }))];
}
/** The items that were in force at a moment: points already earned keep the amounts of their day. */
const pointItemsAt = (versions, at) => {
  let cur = versions[0];
  versions.forEach((v) => { if (v.at <= (at || "")) cur = v; });
  return cur.items;
};
const currentPointItems = (suggestions) => {
  const v = pointVersions(suggestions);
  return v[v.length - 1].items;
};
function applyPointItems(items) {
  POINT_ITEMS = items;
  BUILT_IN_POINT_IDS.forEach((id) => {
    const it = items.find((i) => i.id === id);
    if (it) POINT_RULES[id] = it.amount;
  });
}
/** One line in a family's point history. */
function pointEntries(pin, students, adventures, suggestions) {
  const kids = students.filter((st) => st.familyPin === pin);
  const ids = new Set(kids.map((k) => k.id));
  const nameOf = (id) => kids.find((k) => k.id === id)?.name || "";
  const progTitle = (id) => {
    const p = getProgram(id);
    return p ? splitTitle(p.title)[0] || p.title : "";
  };
  const versions = pointVersions(suggestions);
  const itemAt = (id, at) => pointItemsAt(versions, at).find((i) => i.id === id) || DEFAULT_POINT_ITEMS.find((i) => i.id === id);
  const out = [];
  adventures.filter((a) => ids.has(a.studentId) && !a.canceled).forEach((a) => {
    const detail = `${progTitle(a.programId)} · ${nameOf(a.studentId)}`;
    if (a.attended) {
      const at = a.attendedAt || a.enrolledAt || "";
      const it = itemAt("trip", at);
      if (it.amount > 0) out.push({ key: `trip:${a.studentId}:${a.programId}`, kind: "trip", delta: it.amount, at, title: it.title, detail });
    }
    if (a.parentSurvey) {
      const at = a.parentSurvey.at || "";
      const it = itemAt("survey", at);
      if (it.amount > 0) out.push({ key: `survey:${a.studentId}:${a.programId}`, kind: "survey", delta: it.amount, at, title: it.title, detail });
    }
  });
  reviewRecords(suggestions).filter((r) => r.familyPin === pin && r.status === "approved").forEach((r) => {
    const at = r.decidedAt || r.submittedAt || "";
    const it = itemAt("review", at);
    if (it.amount > 0) out.push({ key: `review:${r.id}`, kind: "review", delta: it.amount, at, title: it.title, detail: progTitle(r.programId) });
  });
  const rows = suggestions.filter((sg) => sg.type === POINT_TYPE && sg.familyPin === pin);
  const cancelled = new Set(rows.map(readRow).filter((r) => r.kind === "void").map((r) => r.target));
  rows.forEach((sg) => {
    const r = readRow(sg);
    if (r.kind === "void") return;
    const title = r.kind === "item" ? r.title || r.name || "Points" : r.kind === "referral" ? r.title || itemAt("referral", r.at || "").title : r.kind === "redeem" ? "Redeemed" : "Adjustment";
    out.push({ key: `pt:${sg.id}`, rowId: sg.id, manual: true, voided: cancelled.has(sg.id), kind: r.kind, delta: Number(r.delta) || 0, at: r.at || "", title, detail: r.kind === "referral" ? r.friend || "" : r.note || "" });
  });
  return out.sort((a, b) => String(b.at).localeCompare(String(a.at)));
}
/** A cancelled entry stays in the history (struck through) but is not counted. */
const pointsBalance = (entries) => entries.reduce((sum, e) => sum + (e.voided ? 0 : e.delta), 0);
/** The points a child's own trips have earned (shown on the teacher's card). */
const carrotPoints = (adventures, studentId) => adventures.filter((a) => a.studentId === studentId && a.attended && !a.canceled).length * POINT_RULES.trip;
/* ================================================================== */
/*  TEACHER ACCOUNTS AND SIGN-UPS                                       */
/*  Every foreign teacher has a name and a number of their own (set by   */
/*  HQ). They can sign up for programs that have not run yet; HQ         */
/*  approves. All of it is stored as create-only rows (the latest wins). */
/* ================================================================== */
const TEACHER_TYPE = "샘";
const TEACHER_JOIN_TYPE = "샘신청";
const TEACHER_JOIN_RESULT_TYPE = "샘신청결과";
const TEACHER_APPLY_TYPE = "샘가입신청"; // a teacher asks for an account (name + the number they want); HQ accepts or declines
/** Teachers waiting for HQ: asked for an account, not accepted and not declined yet. */
function teacherApplications(suggestions, accounts) {
  const rows = (suggestions || []).filter((sg) => sg.type === TEACHER_APPLY_TYPE).map(readRow).filter((r) => r.id).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  const apps = new Map();
  rows.forEach((r) => { if (r.kind === "reject") apps.delete(r.id); else if (r.name && /^\d{4}$/.test(r.pin || "")) apps.set(r.id, { id: r.id, name: String(r.name).trim(), pin: r.pin, phone: r.phone || "", phoneLast4: r.phoneLast4 || "", phoneCode: r.phoneCode || "", at: r.at || "" }); });
  return [...apps.values()].filter((a) => !(accounts || []).some((t) => t.id === a.id)).sort((a, b) => String(b.at).localeCompare(String(a.at)));
}
/** The accounts, worked out from the rows: "add" (name + number), "pin" (new number), "active" (on/off). */
function teacherAccounts(suggestions) {
  const rows = (suggestions || []).filter((sg) => sg.type === TEACHER_TYPE).map(readRow).filter((r) => r.id).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  const map = new Map();
  rows.forEach((r) => {
    const cur = map.get(r.id) || { id: r.id, name: "", pin: "", active: true };
    if (r.kind === "add") { cur.name = r.name; cur.pin = r.pin; cur.active = true; cur.phoneLast4 = r.phoneLast4 || ""; cur.phoneCode = r.phoneCode || ""; cur.phone = r.phone || ""; }
    else if (r.kind === "pin") cur.pin = r.pin;
    else if (r.kind === "phone") { cur.phone = r.phone || ""; cur.phoneLast4 = (r.phone || "").slice(-4); }
    else if (r.kind === "active") cur.active = !!r.active;
    map.set(r.id, cur);
  });
  return [...map.values()].filter((t) => t.name && /^\d{4}$/.test(t.pin)).sort((a, b) => a.name.localeCompare(b.name));
}
const teacherByPin = (accounts, pin) => accounts.find((t) => t.active && t.pin === pin) || null;
/** Most teachers per program (per session when a program has sessions). Sign-ups up to this number confirm by themselves. */
const TEACHER_CAP = 6;
/** HQ can set another number for one program; the latest setting wins. */
function teacherCaps(suggestions) {
  const caps = {};
  (suggestions || []).filter((sg) => sg.type === SETTING_TYPE).map(readRow).filter((r) => r.key === "teacherCap" && r.programId).sort((a, b) => String(a.at).localeCompare(String(b.at))).forEach((r) => {
    const n = Math.round(Number(r.value));
    if (n >= 1 && n <= 50) caps[r.programId] = n;
  });
  return caps;
}
const joinKey = (teacherId, programId, slotId) => `${teacherId}|${programId}|${slotId || ""}`;
/** Every sign-up with where it stands: pending, approved, declined or withdrawn (the latest event wins). */
function teacherJoins(suggestions) {
  const events = [];
  (suggestions || []).forEach((sg) => {
    if (sg.type === TEACHER_JOIN_TYPE) {
      const r = readRow(sg);
      if (r.teacherId && r.programId) events.push({ key: joinKey(r.teacherId, r.programId, r.slotId), at: r.at || "", ev: r.kind === "withdraw" ? "withdraw" : "request", row: r });
    } else if (sg.type === TEACHER_JOIN_RESULT_TYPE) {
      const r = readRow(sg);
      if (r.key) events.push({ key: r.key, at: r.at || "", ev: r.status, row: r });
    }
  });
  events.sort((a, b) => String(a.at).localeCompare(String(b.at)));
  const map = new Map();
  events.forEach((e) => {
    const cur = map.get(e.key);
    if (e.ev === "request") map.set(e.key, { key: e.key, teacherId: e.row.teacherId, programId: e.row.programId, slotId: e.row.slotId || "", note: e.row.note || "", requestedAt: e.at, status: "pending", decidedAt: null });
    else if (!cur) return;
    else if (e.ev === "withdraw") map.set(e.key, { ...cur, status: "withdrawn" });
    else if ((e.ev === "approved" || e.ev === "declined") && cur.status !== "withdrawn") map.set(e.key, { ...cur, status: e.ev, decidedAt: e.at });
  });
  // seats: a sign-up is confirmed by itself while the program (or session) has room; the rest wait until a seat frees up or HQ confirms one
  const list = [...map.values()].sort((a, b) => String(a.requestedAt).localeCompare(String(b.requestedAt)));
  const caps = teacherCaps(suggestions);
  const seats = {};
  const seatKey = (j) => `${j.programId}|${j.slotId}`;
  list.forEach((j) => { if (j.status === "approved") seats[seatKey(j)] = (seats[seatKey(j)] || 0) + 1; });
  list.forEach((j) => {
    if (j.status !== "pending") return;
    if ((seats[seatKey(j)] || 0) < (caps[j.programId] || TEACHER_CAP)) { j.status = "approved"; j.auto = true; j.decidedAt = j.requestedAt; seats[seatKey(j)] = (seats[seatKey(j)] || 0) + 1; }
    else j.status = "waiting";
  });
  return list.reverse();
}
/* ---------- Teacher pay: hours x rate, camps by hand, reset when HQ marks it paid ---------- */
const PAY_TYPE = "수당정산"; // one row per payout (or its undo)
const DEFAULT_PAY_RATE = 30000; // won per hour
/** 3.3% withheld on freelance pay: income tax 3% + local income tax 0.3% (10% of the income tax). Estimate: amounts are cut down to whole won / 10 won. */
function payTax(gross, on = true) {
  const g = Math.max(0, Math.round(gross || 0));
  if (!on) return { gross: g, incomeTax: 0, localTax: 0, tax: 0, net: g, withheld: false };
  const incomeTax = Math.floor(g * 0.03);
  const localTax = Math.floor((incomeTax * 0.1) / 10) * 10;
  return { gross: g, incomeTax, localTax, tax: incomeTax + localTax, net: g - incomeTax - localTax, withheld: true };
}
const won = (n) => `${Math.round(n || 0).toLocaleString("en-US")}원`;
/** "10:30 ~ 12:00" -> 1.5 (0 when there is no clock time to read) */
function parseHours(text) {
  const m = /(\d{1,2}):(\d{2})\s*[~\-–]\s*(\d{1,2}):(\d{2})/.exec(String(text || ""));
  if (!m) return 0;
  const a = Number(m[1]) * 60 + Number(m[2]);
  const b = Number(m[3]) * 60 + Number(m[4]);
  return b > a ? (b - a) / 60 : 0;
}
/** HQ's hourly rate and the amounts typed by hand: per program (everyone on it) or per teacher and program. The latest entry wins; an empty value clears it. */
function paySettings(suggestions) {
  let rate = DEFAULT_PAY_RATE;
  let taxOn = true;
  const amounts = {};
  (suggestions || []).filter((sg) => sg.type === SETTING_TYPE).map(readRow).filter((r) => r.key === "payRate" || r.key === "payAmount" || r.key === "payTax").sort((a, b) => String(a.at).localeCompare(String(b.at))).forEach((r) => {
    if (r.key === "payTax") taxOn = !!r.value;
    else if (r.key === "payRate") { const n = Number(r.value); if (n > 0) rate = Math.round(n); }
    else if (r.scope) { if (r.value === "" || r.value === null || r.value === undefined) delete amounts[r.scope]; else if (Number(r.value) >= 0) amounts[r.scope] = Math.round(Number(r.value)); }
  });
  return { rate, amounts, taxOn };
}
/** Every payout HQ recorded, newest first (undone ones are marked). */
function payPayouts(suggestions) {
  const rows = (suggestions || []).filter((sg) => sg.type === PAY_TYPE).map(readRow).filter((r) => r.id).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  const map = new Map();
  rows.forEach((r) => { if (r.kind === "paid") map.set(r.id, { id: r.id, teacherId: r.teacherId, keys: Array.isArray(r.keys) ? r.keys : [], lines: Array.isArray(r.lines) ? r.lines : null, taxOn: r.taxOn !== false, rate: Number(r.rate) || 0, amount: Number(r.amount) || 0, at: r.at || "", voided: false }); else if (r.kind === "void" && map.has(r.id)) map.get(r.id).voided = true; });
  return [...map.values()].sort((a, b) => String(b.at).localeCompare(String(a.at)));
}
/** What each confirmed teacher earned on programs that are over, and whether it was paid already. */
function teacherEarnings(suggestions, joins, now, adventures = []) {
  const { rate, amounts } = paySettings(suggestions);
  const paidBy = new Map();
  payPayouts(suggestions).filter((p) => !p.voided).forEach((p) => p.keys.forEach((k) => paidBy.set(k, p)));
  return (joins || []).filter((j) => j.status === "approved").map((j) => {
    const p = getProgram(j.programId);
    if (!p || !tripDayPassed(p, now)) return null;
    if (adventures.some((a) => a.programId === j.programId && a.attended && !a.canceled && !feedbackDone(a))) return null; // counted once the feedback is submitted
    const slot = sessionsOf(p).find((x) => x.id === j.slotId) || null;
    const hours = parseHours(infoForSession(infoFrom(p), slot).time);
    let amount = 0;
    let source = "none";
    if (amounts[j.key] !== undefined) { amount = amounts[j.key]; source = "manual"; }
    else if (amounts[j.programId] !== undefined) { amount = amounts[j.programId]; source = "program"; }
    else if (hours > 0) { amount = Math.round(hours * rate); source = "hours"; }
    const paid = paidBy.get(j.key) || null;
    return { key: j.key, teacherId: j.teacherId, programId: j.programId, slotId: j.slotId || "", title: splitTitle(p.title)[0] || p.title, date: p.date || "", slotLabel: slot ? slot.label : "", day: lastDay(p) || "", hours, amount, source, needsAmount: source === "none", paid: !!paid, paidAt: paid ? paid.at : "" };
  }).filter(Boolean).sort((a, b) => String(b.day).localeCompare(String(a.day)));
}

/** Places HQ has used before (name, address, meeting point, short intro): typing the same place name fills them in. The latest save of a name wins. */
function savedPlaces(suggestions) {
  const map = new Map();
  (suggestions || []).filter((sg) => sg.type === SETTING_TYPE).map(readRow).filter((r) => r.key === "place" && r.name).sort((a, b) => String(a.at).localeCompare(String(b.at))).forEach((r) => {
    map.set(String(r.name).trim().toLowerCase(), { name: String(r.name).trim(), venue: r.venue || "", meetingPoint: r.meetingPoint || "", intro: r.intro || "" });
  });
  return [...map.values()].sort((a, b) => a.name.localeCompare(b.name));
}
const mapLink = (address) => `https://map.naver.com/p/search/${encodeURIComponent(address)}`;
/** Names of the teachers HQ approved for a program (for the team form). */
const confirmedTeacherNames = (joins, accounts, programId, slotId) => [...new Set(joins.filter((j) => j.programId === programId && j.status === "approved" && (slotId === undefined || !j.slotId || j.slotId === slotId)).map((j) => (accounts.find((t) => t.id === j.teacherId) || {}).name).filter(Boolean))];
/** Suggests teams for the children who have none. Teams that still have room are filled first; then each level with children gets
 *  a team for every free teacher (the biggest levels first, an extra teacher goes where a team is most over `max`), the children split evenly.
 *  Children of a level without a teacher stay without a team. Nothing is changed here: it only returns the plan. */
function planTeams({ loose, teams, counts, free, max }) {
  const byLevel = new Map();
  loose.forEach((k) => byLevel.set(k.level, [...(byLevel.get(k.level) || []), k]));
  const fills = [];
  teams.forEach((t) => {
    const kids = byLevel.get(t.level) || [];
    const room = Math.max(0, max - (counts[t.id] || 0));
    if (room > 0 && kids.length) fills.push({ teamId: t.id, level: t.level, teacher: t.teacher, kids: kids.splice(0, room) });
  });
  const levels = [...byLevel.entries()].filter(([, ks]) => ks.length).sort((a, b) => b[1].length - a[1].length || String(a[0]).localeCompare(String(b[0])));
  const pool = [...free];
  const assigned = new Map(levels.map(([l]) => [l, []]));
  levels.forEach(([l]) => { if (pool.length) assigned.get(l).push(pool.shift()); });
  while (pool.length) {
    let best = null;
    levels.forEach(([l, ks]) => {
      const n = assigned.get(l).length;
      if (n && ks.length / n > max && (!best || ks.length / n > best.ratio)) best = { l, ratio: ks.length / n };
    });
    if (!best) break;
    assigned.get(best.l).push(pool.shift());
  }
  const made = [];
  const leftover = [];
  let needMore = 0;
  levels.forEach(([l, ks]) => {
    const names = assigned.get(l);
    needMore += Math.max(0, Math.ceil(ks.length / max) - names.length);
    if (!names.length) { leftover.push(...ks); return; }
    const base = Math.floor(ks.length / names.length);
    const extra = ks.length % names.length;
    let at = 0;
    names.forEach((teacher, i) => {
      const size = base + (i < extra ? 1 : 0);
      made.push({ level: l, teacher, kids: ks.slice(at, at + size) });
      at += size;
    });
  });
  return { fills, teams: made, leftover, needMore };
}

/** A free 4-digit number (not the HQ number, not used by another teacher, nothing too easy to guess). */
function freeTeacherPin(accounts, hqPin) {
  const taken = new Set([hqPin, ...accounts.filter((t) => t.active).map((t) => t.pin)]);
  for (let i = 0; i < 500; i++) {
    const pin = String(Math.floor(Math.random() * 10000)).padStart(4, "0");
    if (taken.has(pin) || /^(\d)\1{3}$/.test(pin) || ["1234", "4321", "0123", "2580"].includes(pin)) continue;
    return pin;
  }
  return "";
}
const isSystemRow = (sg) => isWish(sg) || isVisit(sg) || isPointRow(sg) || sg.type === SETTING_TYPE || sg.type === TEACHER_TYPE || sg.type === TEACHER_JOIN_TYPE || sg.type === TEACHER_JOIN_RESULT_TYPE || sg.type === TEACHER_APPLY_TYPE || sg.type === PAY_TYPE || sg.type === PHONE_TYPE; // not shown as parent opinions
/** The teachers' login number: the latest one HQ saved, else the default. */
const currentGuidePin = (suggestions) => {
  const rows = (suggestions || []).filter((sg) => sg.type === SETTING_TYPE).map(readRow).filter((r) => r.key === "guidePin" && /^\d{4}$/.test(r.value)).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  return rows.length ? rows[rows.length - 1].value : GUIDE_PIN_DEFAULT;
};
const lastDays = (n) => {
  const out = [];
  const base = new Date(`${kstDay()}T12:00:00+09:00`);
  for (let i = n - 1; i >= 0; i--) out.push(kstDay(new Date(base.getTime() - i * 86400000)));
  return out;
};
function visitStats(suggestions) {
  const seen = new Set();
  const rows = [];
  suggestions.forEach((sg) => {
    if (!isVisit(sg)) return;
    const m = /^visit-(.+)-(\d{4}-\d{2}-\d{2})$/.exec(sg.id);
    if (!m || seen.has(sg.id)) return;
    seen.add(sg.id);
    rows.push({ pin: m[1], day: m[2] });
  });
  const today = kstDay();
  const byDay = {};
  const daysPerFamily = {};
  rows.forEach((r) => {
    byDay[r.day] = (byDay[r.day] || 0) + 1;
    (daysPerFamily[r.pin] = daysPerFamily[r.pin] || new Set()).add(r.day);
  });
  return {
    today: byDay[today] || 0,
    total: rows.length,
    families: Object.keys(daysPerFamily).length,
    returning: Object.values(daysPerFamily).filter((d) => d.size >= 2).length,
    week: lastDays(7).map((day) => ({ day, count: byDay[day] || 0 })),
  };
}
const wishesFor = (suggestions, programId) => suggestions.filter((sg) => isWish(sg) && !sg.resolved && sg.id.endsWith(`-${programId}`) && sg.id === wishId(sg.familyPin, programId));

function SuggestionBox({ suggestions, familyPin, onAdd }) {
  const [open, setOpen] = useState(false);
  const [type, setType] = useState(SUGGESTION_TYPES[0]);
  const [message, setMessage] = useState("");
  const mine = suggestions.filter((s) => s.familyPin === familyPin && !isSystemRow(s)).slice().reverse();

  const submit = () => {
    if (!message.trim()) return;
    onAdd({ type, message: message.trim(), familyPin });
    setMessage("");
    setOpen(false);
  };

  return (
    <div className="bg-white rounded-2xl p-4">
      <button onClick={() => setOpen((o) => !o)} className="focus-ring tap w-full flex items-center justify-between">
        <span className="f-display text-[20px] font-bold" style={{ color: C.green }}>건의사항 · 장소 요청</span>
        <ChevronRight size={16} color="#C9BFA8" className={`transition-transform ${open ? "rotate-90" : ""}`} />
      </button>

      {open && (
        <div className="mt-3">
          <div className="flex gap-2 mb-3">
            {SUGGESTION_TYPES.map((t) => (
              <button
                key={t}
                onClick={() => setType(t)}
                aria-pressed={type === t}
                className="focus-ring tap flex-1 text-[15px] f-body font-bold rounded-xl py-2"
                style={{ background: type === t ? C.green : C.cream, color: type === t ? "white" : C.charcoal, border: `1px solid ${type === t ? C.green : C.beige}` }}
              >
                {t}
              </button>
            ))}
          </div>
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            rows={3}
            placeholder="의견이나 가보고 싶은 장소를 남겨주세요..."
            aria-label="건의사항 또는 장소 요청 내용"
            className="focus-ring w-full rounded-xl p-3 f-body text-[17px] outline-none mb-3"
            style={{ background: C.cream, border: `1px solid ${C.beige}` }}
          />
          <PrimaryButton onClick={submit} disabled={!message.trim()}>보내기</PrimaryButton>
        </div>
      )}

      {mine.length > 0 && (
        <div className="mt-4 space-y-2">
          {mine.map((s) => (
            <div key={s.id} className="rounded-xl p-3" style={{ background: C.cream }}>
              <div className="flex items-center justify-between mb-1">
                <span className="f-body text-[14px] font-bold" style={{ color: C.orange }}>{s.type}</span>
                <span
                  className="f-body text-[13px] font-bold px-2 py-0.5 rounded-full"
                  style={{ background: s.resolved ? "#DCF3E4" : C.beige, color: s.resolved ? "#1F7A44" : "#8A8060" }}
                >
                  {s.resolved ? "확인함" : "검토중"}
                </span>
              </div>
              <p className="f-body text-[17px]" style={{ color: C.charcoal }}>{s.message}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/** In-app notices for a parent, worked out from what already exists (nothing extra is stored). */
function parentNotices(children, adventures, suggestions) {
  const list = [];
  const infoShown = new Set(); // one "안내" notice per program, even with siblings
  children.forEach((child) => {
    adventures
      .filter((a) => a.studentId === child.id)
      .forEach((a) => {
        const program = getProgram(a.programId);
        if (!program) return;
        const base = `${child.name} · ${splitTitle(program.title)[0] || program.title}`;
        if (feedbackSent(a)) {
          list.push({ key: `${base}-report`, icon: "📝", title: "선생님 리포트가 도착했어요", text: base, action: "리포트 보기", kind: "report", childId: child.id });
        }
        // with time slots the notice is the slot's own, and only children of a slot whose notice was shared get it
        const slots = sessionsOf(program);
        const slot = sessionOf(program, a);
        const shown = slots.length ? (slot && isNoticeOut(program, slot) ? infoForSession(infoFrom(program), slot) : null) : isNoticeOut(program, null) ? infoFrom(program) : null;
        const infoKey = `${program.id}-${slot ? slot.id : ""}`;
        if (shown && hasInfo(shown) && !a.attended && !infoShown.has(infoKey)) {
          infoShown.add(infoKey);
          const when = [program.date, shown.time].filter(Boolean).join(" ");
          list.push({ key: `${infoKey}-info`, icon: "📍", title: "체험 안내가 도착했어요", text: `${splitTitle(program.title)[0] || program.title} · ${slot ? `${slot.label} · ` : ""}${when}`, action: "확인하기", kind: "info", childId: child.id, programId: program.id, sessionId: slot ? slot.id : null });
        }
        if (FEATURES.parentAdvice && a.advice?.sent && Date.now() - Date.parse(a.advice.sent.sentAt) < 14 * 86400000) {
          list.push({ key: `${base}-advice`, icon: "💬", title: "선생님이 학습 조언을 보냈어요", text: base, action: "읽어 보기", kind: "report", childId: child.id });
        }
        const team = teamOf(program, a);
        if (team && !a.attended) {
          list.push({ key: `${base}-team`, icon: "🧑‍🏫", title: "팀과 담당 선생님이 정해졌어요", text: `${base} · ${teamForParent(team)}`, action: "확인하기", kind: "team", programId: program.id, sessionId: a.sessionId || null });
        }
        if (a.attended && !a.parentSurvey) {
          list.push({ key: `${base}-survey`, icon: "📋", title: "체험 후 설문을 남겨 주세요", text: `${base} · 1~2분이면 돼요`, action: "설문하기", kind: "survey", childId: child.id, programId: program.id });
        }
        if (getStatus(a) === "completed") return;
        if (isLive(program) && !a.attended) {
          list.push({ key: `${base}-today`, icon: "🎒", title: "오늘은 체험 날이에요!", text: `${base} · 현장 단계가 열렸어요`, action: "시작하기", kind: "adventure", childId: child.id });
        } else if (a.attended && !a.afterCompleted && isReviewOpen(program)) {
          list.push({ key: `${base}-review`, icon: "✏️", title: "복습이 열렸어요", text: `${base} · 퀴즈를 풀고 점수를 확인해요`, action: "복습하기", kind: "adventure", childId: child.id });
        } else if (!a.beforeCompleted) {
          list.push({ key: `${base}-prep`, icon: "📚", title: "예습이 기다리고 있어요", text: `${base} · ${program.date}`, action: "예습하기", kind: "adventure", childId: child.id });
        }
      });
  });
  // a trip the family finished and has not yet sent a review link for: one reminder per program (only while the review item has points)
  if (suggestions) applyPointItems(currentPointItems(suggestions));
  if (suggestions && POINT_RULES.review > 0) {
    const records = reviewRecords(suggestions);
    const done = new Set();
    children.forEach((child) => {
      adventures.filter((a) => a.studentId === child.id && a.attended && !a.canceled).forEach((a) => {
        const program = getProgram(a.programId);
        if (!program || done.has(program.id)) return;
        done.add(program.id);
        const last = latestReview(records, child.familyPin, program.id);
        if (last && last.status !== "rejected") return;
        list.push({ key: `${program.id}-extreview`, icon: "🥕", title: `외부 후기 작성하고 ${POINT_RULES.review}P 받기`, text: splitTitle(program.title)[0] || program.title, action: "링크 남기기", kind: "points", programId: program.id });
      });
    });
  }
  const priority = { "🎒": 0, "📍": 1, "🧑‍🏫": 2, "💬": 3, "📝": 4, "📋": 5, "✏️": 6, "📚": 7, "🥕": 8 };
  return list.sort((x, y) => priority[x.icon] - priority[y.icon]);
}

function ProgramBrowse({ children, adventures, suggestions, familyPin, onToggleWish }) {
  const [openId, setOpenId] = useState(null);
  // only programs that have not run yet, and that none of the family's children has applied to
  const cards = upcomingPrograms(adventures)
    .map((p) => ({
      program: p,
      pending: children.filter((c) => !adventures.some((a) => a.studentId === c.id && a.programId === p.id)),
    }))
    .filter((x) => x.pending.length > 0);

  return (
    <div id="browse-programs">
      <div className="mb-3 mt-6">
        <p className="f-display text-[24px] font-bold leading-tight" style={{ color: C.green }}>예정 체험</p>
        <p className="f-body text-[14px] text-gray-500 mt-1.5">마음에 드는 체험은 ♡ 찜해 두세요. 신청은 카카오톡으로 문의해 주세요.</p>
        {KAKAO_CHAT_URL && (
          <a href={KAKAO_CHAT_URL} target="_blank" rel="noopener noreferrer" className="focus-ring tap inline-block f-body text-[15px] font-bold rounded-xl px-3 py-1.5 mt-2" style={{ background: "#FEE500", color: "#3A1D1D" }}>
            카카오톡으로 문의하기
          </a>
        )}
      </div>
      {cards.length === 0 ? (
        <div className="bg-white rounded-2xl p-4 text-center">
          <p className="f-body text-[17px] text-gray-400">지금 신청할 수 있는 새 체험이 없어요. 새 체험이 열리면 여기에 나타나요.</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl overflow-hidden">
          {cards.map(({ program: p, pending }) => {
            const message = `${pending.map((c) => c.name).join(", ")} · ${p.title} 찜`;
            const liked = suggestions.some((sg) => sg.id === wishId(familyPin, p.id) && !sg.resolved);
            const open = openId === p.id;
            const fits = pending.some((c) => (p.levels || [p.level]).includes(c.level));
            const slots = sessionsOf(p);
            return (
              <div key={p.id} className="p-3 border-b last:border-b-0" style={{ borderColor: C.beige }} data-testid="upcoming-card">
                <div className="flex items-center gap-3">
                  <button onClick={() => setOpenId(open ? null : p.id)} aria-expanded={open} className="focus-ring tap flex-1 min-w-0 flex items-center gap-3 text-left">
                    <span className="self-stretch w-1.5 rounded-full shrink-0" style={{ background: themeBar(p) }} aria-hidden="true" />
                    <span className="min-w-0 py-0.5">
                      <span className="block f-headline text-[23px] leading-snug" style={{ color: C.green }}>{splitTitle(p.title)[0] || p.title}</span>
                      {splitTitle(p.title)[1] && <span className="block f-body text-[15px] text-gray-500 leading-snug">{splitTitle(p.title)[1]}</span>}
                      <span className="block f-body text-[14px] text-gray-400 mt-0.5">{p.date} · Level {levelLabel(p)}</span>
                      {fits && <span className="inline-block f-body text-[13px] font-bold px-2.5 py-0.5 rounded-full mt-1" style={{ background: "#EAF7EF", color: "#1F7A44" }}>우리 아이 레벨에 맞아요</span>}
                    </span>
                  </button>
                  <button
                    onClick={() => onToggleWish({ familyPin, programId: p.id, message })}
                    aria-pressed={liked}
                    aria-label={liked ? "찜 취소" : "찜하기"}
                    className="focus-ring tap shrink-0 w-10 h-10 rounded-full text-[21px]"
                    style={{ background: liked ? "#FFE3E0" : C.cream, color: liked ? "#C0392B" : "#B9AE99" }}
                  >
                    {liked ? "♥" : "♡"}
                  </button>
                </div>
                {open && (
                  <div className="mt-3">
                    {p.themeKo && <p className="f-body text-[15px]" style={{ color: C.charcoal }}>{p.themeKo}</p>}
                    {(p.locationKo || p.location) && <p className="f-body text-[14px] text-gray-400 mt-1">📍 {p.locationKo || p.location}</p>}
                    {slots.length > 0 && <p className="f-body text-[14px] text-gray-400 mt-0.5">🕘 {slots.map((x) => (x.time ? `${x.label} ${x.time}` : x.label)).join(" · ")}</p>}
                    {slots.length === 0 && isNoticeOut(p, null) && p.info.time && <p className="f-body text-[14px] text-gray-400 mt-0.5">⏰ {p.info.time}</p>}
                    {isNoticeOut(p, null) && feeText(p.info) && <p className="f-body text-[14px] text-gray-400 mt-0.5">💰 {feeText(p.info)}</p>}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

