                  <input value={x.meetingPoint || ""} onChange={(e) => upd({ meetingPoint: e.target.value })} placeholder={tr("모이는 곳 (다르면)")} aria-label={tr("시간대 모이는 곳")} className={small} style={{ ...st, flex: 1.3 }} />
